function N.sim(Eq)
local Fq=H.sim and I.simRes[Eq.key]
if Fq and Fq.p and os.time()-(Fq.at or 0)<6*3600 and(Fq.sig==N.teamSig()or Fq.sig==N.ownSig())then
return Fq
end
return nil
end
function N.ownSig()
local Gq=(type(I.savedTeam)==Qkc[1366]and#I.savedTeam>0 and I.savedTeam)or(I.train.on and I.train.on.base)
if type(Gq)~=Qkc[1366]or#Gq==0 then
return nil
end
if N._ownAt and L.now()-N._ownAt<20 then
return N._own
end
local Hq=G.session()
local Iq={}
for Jq,Kq in ipairs(Gq)do
local Lq=Hq and Hq.collection:get_unit_by_uuid(Kq)
if Lq then
table.insert(Iq,Lq)
end
end
N._own,N._ownAt= #Iq>0 and V.sig(Iq)or nil,L.now()
return N._own
end
function N.nextAct(Mq)
N._next=N._next or{}
local Nq=N._next[Mq]
if Nq==nil then
local Oq,Pq=pcall(G.PSC.get_next_story_level,Mq)
Nq=Oq and Pq or false
N._next[Mq]=Nq
end
return Nq or nil
end
function N.winP(Qq)
local Rq=Qq.rec
local Sq=Qq.p0 or N.PRIOR_WIN[Qq.kind]or 0.7
local Tq=N.sim(Qq)
if Tq and not(Tq.trust and not Tq.trust.ok)then
local Uq=Tq.calibrated or Rq.runs>0
local Vq=(Tq.trust and Tq.trust.ok)and 6 or(Uq and 3 or 1.5)
local Wq=Uq and 0 or 2
return(Rq.wins+Sq*Wq+Tq.p*Vq)/(Rq.runs+Wq+Vq)
end
return(Rq.wins+Sq*2)/(Rq.runs+2)
end
function N.minutes(Xq)
local Yq=Xq.rec
local Zq=tonumber(Yq.timed)or 0
local _q=Xq.kind==Qkc[1385]and I.simRes[Xq.key]
local ar=(Zq>0 and Yq.sec>0)and(Yq.sec/Zq/60)or(_q and tonumber(_q.minutes))or N.PRIOR_MIN[Xq.kind]or 6
return ar+N.OVERHEAD
end
function N.score(br)
local cr,dr=((br.kind==Qkc[1383]and br.rec.runs>0)or br.kind==Qkc[1385])and 1 or(br.kind==Qkc[1386]and br.p0)or N.winP(br),N.minutes(br)
local er,fr,gr=pcall(cb.modeBonus,br)
if er and(fr or 0)>0 then
br.teamBonus=fr
if not tostring(br.why):find(Qkc[1677],1,true)then
br.why=(br.why or Qkc[295])..Qkc[1552]..gr
end
end
local hr=cr*(br.value+(br.teamBonus or 0))/dr
br.baseScore=hr
local ir,jr,kr=pcall(ab.valueFor,br)
if ir and jr>0 then
local lr=cr*(br.value+jr)/(dr*kr)
if lr>hr then
hr,br.train=lr,jr
