if not(H.summonApril and kw and kw.step==Qkc[1710]and kw.coins>=kw.itemCost and kw.itemCost>0)then
return
end
if j.req.back.eshop and L.now()<j.req.back.eshop then
return
end
local lw,mw=j.request(Qkc[1757],Qkc[1632],kw.item,Qkc[1383],Qkc[1633],Qkc[1503])
local nw=L.now()
while L.now()-nw<4 and W.have(kw.item)<1 do
task.wait(0.25)
end
local ow=(G.Items[kw.item]or{}).name or kw.item
if W.have(kw.item)>0 then
Q.add(ow,kw.itemCost,Qkc[1740],Qkc[1758]..M.name(kw.to))
if j.notify then
j.notify(Qkc[71],Qkc[1759]..ow..Qkc[1760]..M.name(kw.id),Qkc[1761])
end
pcall(W.refresh)
else
j.log(1,Qkc[1762],Qkc[1763]..tostring(kw.item)..Qkc[1647]..tostring(lw and mw or Qkc[1614])..Qkc[1648])
j.backoff(Qkc[1757],900)
end
end
function O.codes()
if not H.codes then
return j.status(Qkc[99],Qkc[1764])
end
local pw=G.prof()
if not pw then
return
end
local qw=pw.redeemed_codes or{}
local rw,sw={},{}
for tw,uw in ipairs(G.CODES)do
local vw=tonumber(I.codes[uw])
if qw[uw]then
if vw and vw>0 then
table.insert(sw,uw)
I.codes[uw]= -1
end
elseif os.time()-(vw or 0)>86400 and(vw or 0)>=0 then
I.codes[uw]=os.time()
local ww=j.request(Qkc[1765],Qkc[1766],uw)
if ww then
table.insert(rw,uw)
end
task.wait(1)
end
end
if#sw>0 then
j.log(1,Qkc[1767],Qkc[1768]..table.concat(sw,Qkc[1461]))
end
if#rw>0 then
j.log(1,Qkc[1767],Qkc[1769]..table.concat(rw,Qkc[1461])..Qkc[1770])
end
j.saveSoon()
local xw=0
for yw,zw in ipairs(G.CODES)do
if not qw[zw]then
xw=xw+1
end
end
j.status(Qkc[99],#rw>0 and(Qkc[1769]..table.concat(rw,Qkc[1461]))or(xw==0 and Qkc[1771]or(xw..Qkc[1772])))
end
function W.copies(Aw,Bw,Cw)
