pcall(N.pick)
end
local Iw={}
for Jw,Kw in ipairs(N.lastScored or{})do
if Kw.level then
Iw[Kw.level]=Kw
end
end
local Lw,Mw
for Nw,Ow in ipairs(Hw or{})do
local Pw=Iw[Ow.level]
local Qw,Rw=pcall(function()
return Pw and N.minutes(Pw)or 10
end)
local Sw=Ow.per*(Pw and(Pw.p or 0.5)or 0.5)/math.max(1,Qw and Rw or 10)
if not Mw or Sw>Mw then
Lw,Mw=Ow,Sw
