function W.planItem(Tw,Uw)
local Vw=W.have(Tw)
if Vw>=Uw then
return{item=Tw,done=true}
end
local Ww=W.sources()[Tw]
if Ww and Ww[1]then
return{item=Tw,need=Uw,have=Vw,farm=Tw,farmNeed=Uw-Vw,levels=Ww}
end
local Xw=G.SaleEvent[Tw]
if Xw and type(Xw.resource_cost)==Qkc[1366]then
return{item=Tw,need=Uw,have=Vw,eventShop=true,cost=tonumber(Xw.resource_cost.amount)or 0,currency=Xw.resource_cost.id,farmNeed=0}
end
for Yw,Zw in pairs(I.raidShop)do
if Zw.id==Tw and Zw.costItem and(Zw.stock==Qkc[1773]or(tonumber(Zw.stock)or 0)>0)then
local _w=W.sources()[Zw.costItem]
local ax=Zw.cost*(Uw-Vw)
local bx=W.have(Zw.costItem)
return{item=Tw,need=Uw,have=Vw,shopKey=Yw,costItem=Zw.costItem,cost=Zw.cost,farm=Zw.costItem,farmNeed=math.max(0,ax-bx),levels=_w or{}}
end
end
for cx,dx in pairs(N.PORTALS)do
if dx.item==Tw then
return{item=Tw,need=Uw,have=Vw,farm=Tw,farmNeed=Uw-Vw,portal=cx,levels={{level=dx.level,per=N.portalPer(cx)}}}
end
end
return{item=Tw,need=Uw,have=Vw,unknown=true}
end
N.PORTALS={portal_item__shibuya={level=Qkc[1774],item=Qkc[1775],from=Qkc[1776],per=10,drops=1}}
