N._spawns={}
function N.levelSpawns(vx,wx)
local xx=tostring(vx)
local yx=N._spawns[xx]
if yx and os.time()-yx.at<3600 then
return yx.n
end
local zx=0
pcall(function()
local Ax=G.Levels[vx]
local Bx=V.info(V.slim and V.slim(Ax)or Ax,Qkc[1778]..xx)
local Cx=false
for Dx,Ex in pairs(Bx.configs or{})do
if wx[Dx]or(type(Ex)==Qkc[1366]and wx[Ex.unit_id or Qkc[295]])then
Cx=true
break
end
end
if not Cx then
return
end
local Fx=Bx.infinite and math.floor(N.infReach(Qkc[1510]..xx)+0.5)or Bx.total
local function Gx(Hx)
local Ix=Bx.configs[Hx]
return wx[Hx]or(type(Ix)==Qkc[1366]and wx[Ix.unit_id or Qkc[295]])
end
for Jx=1,math.min(Fx or 30,200)do
if Bx.infinite then
local Kx,Lx=pcall(G.LU.Infinite.infinite_amt_scale,Jx,Bx.ld)
local Mx,Nx=0,0
for Ox,Px in pairs(Bx.configs)do
if type(Px)==Qkc[1366]and Px.spawn_tier_normal then
local Qx,Rx=pcall(G.LU.Infinite.infinite_get_normal_unit_chance,Px,Jx)
Rx=Qx and tonumber(Rx)or 0
Mx=Mx+Rx
if Gx(Ox)then
Nx=Nx+Rx
end
end
end
if Mx>0 then
zx=zx+(Kx and tonumber(Lx)or 10)*Nx/Mx
end
else
local Sx=Bx.list[Jx]
for Tx,Ux in ipairs(L.list(Sx and Sx.wave))do
if Gx(Ux.unit)then
zx=zx+(tonumber(Ux.amount)or 1)
end
end
end
end
zx=math.floor(zx+0.5)
end)
N._spawns[xx]={n=zx,at=os.time()}
return zx
end
function N.missionValue(Vx)
local Wx=G.session()
local Xx,Yx=0,nil
for Zx,_x in pairs(Wx and Wx.quest_handler.quest_profile_data.quests or{})do
local ay=_x.quest_info
local cy=ay and ay.quest_class
if cy and cy.class==Qkc[1779]and type(cy.unit_ids)==Qkc[1366]then
local dy=tonumber(cy.amount)or 0
local ey=dy-(tonumber(_x.quest_progress and _x.quest_progress.amount)or 0)
if ey>0 then
local fy=N.levelSpawns(Vx,cy.unit_ids)
if fy>0 then
local gy=tonumber(ay.quest_reward and ay.quest_reward.gem_reward)or 0
for hy,iy in pairs(ay.quest_reward and ay.quest_reward.item or{})do
if type(iy)==Qkc[1366]and iy.item_id then
gy=gy+N.itemValue(iy.item_id,tonumber(iy.max_amount or iy.amount or iy.min_amount)or 1)
end
end
Xx=Xx+gy*math.min(1,fy/ey)
Yx=string.format(Qkc[1780],tostring(ay.quest_name),L.fmt(dy-ey),L.fmt(dy),L.fmt(math.min(fy,ey)))
end
end
end
end
return Xx,Yx
end
function N.portalKinds()
