local FA,GA=tonumber(DA.tierRank)or 0,tonumber(EA.tierRank)or 0
if FA~=GA then
return FA>GA
end
local HA,IA=tonumber(DA.scoreFull)or 0,tonumber(EA.scoreFull)or 0
if HA~=IA then
return HA>IA
end
return tostring(DA.uuid)<tostring(EA.uuid)
end)
I.goalsTop={}
for JA,KA in ipairs(CA)do
if JA<=10 or KA.pinned then
table.insert(I.goalsTop,{uuid=KA.uuid,from=KA.from,to=KA.to,ready=KA.ready,intoTeam=KA.intoTeam,unknown=KA.unknown,hidden=KA.hidden,pinned=KA.pinned,text=W.text(KA)})
