P.placeLog=P.placeLog or{}
table.insert(P.placeLog,{t=math.floor(L.now()-(P.startT or L.now())),w=P.wave(),id=hHb.id,x=math.floor(kHb.X),z=math.floor(kHb.Z),cover=math.floor((lHb or 0)+0.5),why=tostring(iHb):sub(1,90)})
